return [{ json: { ...input, execution_id: executionId, status: 'accepted', estimated_duration_ms: 90000, workflow_version: 'v1' } }];

// ─────────────────────────────────────────────────────────────────────────
// CROSS-PLATFORM ANALYTICS — connect real APIs here (all already defined
// in backend/.env.example, reused by modules/analytics-hub for the same
// purpose): SPOTIFY_CLIENT_ID/SECRET, YOUTUBE_API_KEY,
// INSTAGRAM_ACCESS_TOKEN, TIKTOK_ACCESS_TOKEN. Comparison against the prior
// snapshot happens on the DATIAM side once results are posted back — this
// node does not fabricate stream/follower counts.
// Credential values are injected upstream by the 'Load Credential Flags'
// node (Set node expressions) since Code nodes cannot access $env directly.
// ─────────────────────────────────────────────────────────────────────────
const input = $input.first().json;
const missing = [];
if (!input.SPOTIFY_CLIENT_ID || !input.SPOTIFY_CLIENT_SECRET) missing.push('SPOTIFY_CLIENT_ID', 'SPOTIFY_CLIENT_SECRET');
if (!input.YOUTUBE_API_KEY) missing.push('YOUTUBE_API_KEY');
if (!input.INSTAGRAM_ACCESS_TOKEN) missing.push('INSTAGRAM_ACCESS_TOKEN');
if (!input.TIKTOK_ACCESS_TOKEN) missing.push('TIKTOK_ACCESS_TOKEN');

return [{ json: {
  mission_id: input.mission_id,
  execution_id: input.execution_id,
  status: missing.length ? 'partial' : 'completed',
  summary: missing.length ? `Analytics Intelligence ready — waiting on: ${missing.join(', ')}` : 'Analytics refresh complete',
  results: {
    spotify_streams: null,
    apple_streams: null,
    youtube: null,
    tiktok: null,
    instagram: null,
    followers: null,
    playlist_additions: null,
    save_rate: null,
    listener_growth: null,
    missing_credentials: missing,
  },
} }];
